// Validate what the portal sent before spending a Graph call on it. The app composes
// subject + body (see app/notify.py — deliberately, so the copy lives in git), so this node
// only checks the shape and never rewrites the wording.
const b = $input.first().json.body || {};
for (const k of ['to', 'subject', 'body']) {
  if (!b[k] || String(b[k]).trim() === '') {
    throw new Error(`3PL account email: missing "${k}" in payload`);
  }
}
if (!String(b.to).includes('@')) {
  throw new Error(`3PL account email: "${b.to}" is not an address`);
}
return [{ json: {
  to: String(b.to).trim(),
  subject: String(b.subject),
  body: String(b.body),
  purpose: b.purpose || 'reset',
  // Empty replyTo is fine — the Graph node below omits the header when it's blank.
  replyTo: (b.reply_to || '').trim(),
} }];
